"""MPS implementations for Qwen gated-delta helper ops."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Any

import torch

from kestrel_kernels.gated_delta.fallback import (
    causal_conv1d_packed_torch,
    causal_conv1d_update_indexed_torch,
    gated_rmsnorm_torch,
    packed_prefill_prepare_torch,
    packed_recurrent_gated_delta_rule_decode_replay_indexed_torch,
    packed_recurrent_gated_delta_rule_prefill_torch,
)
from kestrel_kernels.gated_delta.workspace import (
    PackedGatedDeltaPrefillWorkspace,
    _packed_prefill_prepare_inputs_have_supported_layout,
    active_token_prefix,
    allocate_packed_gated_delta_prefill_workspace as _allocate_prefill_workspace,
)
from kestrel_kernels.mps import _native
from kestrel_kernels.runtime import _resolve_packed_prefill_topology_offsets

_QWEN_HEAD_DIM = 128
_MPS_REPLAY_CAPACITIES = (1, 2, 4, 8, 16)


def _infer_gqa_shape_from_mixed(
    mixed_dim: int,
    num_v_heads: int,
    head_dim: int = _QWEN_HEAD_DIM,
) -> tuple[int, int, int] | None:
    if num_v_heads <= 0:
        return None
    value_dim = num_v_heads * head_dim
    qk_packed_dim = mixed_dim - value_dim
    if qk_packed_dim <= 0 or qk_packed_dim % (2 * head_dim) != 0:
        return None
    num_k_heads = qk_packed_dim // (2 * head_dim)
    if num_k_heads <= 0 or num_v_heads % num_k_heads != 0:
        return None
    return (num_k_heads, num_v_heads, head_dim)


def supports_packed_gdn_mps(
    device: torch.device | str,
    dtype: torch.dtype,
    num_k_heads: int,
    num_v_heads: int,
    head_dim: int,
) -> bool:
    device = torch.device(device)
    return (
        _native.ops is not None
        and device.type == "mps"
        and dtype in (torch.float16, torch.float32)
        and head_dim == _QWEN_HEAD_DIM
        and num_k_heads > 0
        and num_v_heads > 0
        and num_v_heads % num_k_heads == 0
    )


def _conv_x_2d(x: torch.Tensor) -> torch.Tensor | None:
    if x.ndim == 3 and x.shape[-1] == 1:
        return x.squeeze(-1)
    if x.ndim == 2:
        return x
    return None


def _conv_activation_supported(activation: str | None) -> tuple[bool, bool]:
    if activation in (None, "none", ""):
        return True, False
    if activation in ("silu", "swish"):
        return True, True
    return False, False


def _supports_native_causal_conv1d_update_indexed(
    x: torch.Tensor,
    conv_state: torch.Tensor,
    weight: torch.Tensor,
    state_indices: torch.Tensor,
    bias: torch.Tensor | None,
    activation: str | None,
    out: torch.Tensor,
) -> tuple[bool, bool]:
    x2 = _conv_x_2d(x)
    if x2 is None:
        return False, False
    activation_supported, apply_silu = _conv_activation_supported(activation)
    if not activation_supported:
        return False, False
    if _native.ops is None or bias is not None:
        return False, apply_silu
    if x2.ndim != 2 or conv_state.ndim != 3 or weight.ndim != 2:
        return False, apply_silu
    if x2.numel() == 0 or conv_state.numel() == 0 or weight.numel() == 0:
        return False, apply_silu
    return (
        x2.device.type == "mps"
        and conv_state.device.type == "mps"
        and weight.device.type == "mps"
        and state_indices.device.type == "mps"
        and out.device.type == "mps"
        and x2.dtype in (torch.float16, torch.float32)
        and conv_state.dtype == x2.dtype
        and weight.dtype == x2.dtype
        and out.dtype == x2.dtype
        and state_indices.dtype == torch.long
        and out.shape == x2.shape
        and conv_state.shape[1] == x2.shape[1]
        and weight.shape == conv_state.shape[1:]
        and state_indices.shape == (x2.shape[0],)
        and x2.stride(-1) == 1
        and conv_state.is_contiguous()
        and weight.is_contiguous()
        and state_indices.is_contiguous()
        and out.is_contiguous()
    ), apply_silu


def causal_conv1d_update_indexed_mps(
    x: torch.Tensor,
    conv_state: torch.Tensor,
    weight: torch.Tensor,
    state_indices: torch.Tensor,
    bias: torch.Tensor | None = None,
    activation: str | None = "silu",
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    x2 = _conv_x_2d(x)
    if out is None and x2 is not None:
        out = torch.empty_like(x2, memory_format=torch.contiguous_format)
    supported = False
    apply_silu = False
    if out is not None:
        supported, apply_silu = _supports_native_causal_conv1d_update_indexed(
            x,
            conv_state,
            weight,
            state_indices,
            bias,
            activation,
            out,
        )
    if supported:
        _native.ops.causal_conv1d_update_indexed(
            out,
            x2,
            conv_state,
            weight,
            state_indices,
            apply_silu,
        )
        return out
    return causal_conv1d_update_indexed_torch(
        x,
        conv_state,
        weight,
        state_indices,
        bias,
        activation,
        out=out,
    )


def causal_conv1d_packed_mps(
    x: torch.Tensor,
    weight: torch.Tensor,
    seq_idx: torch.Tensor | None = None,
    bias: torch.Tensor | None = None,
    activation: str | None = "silu",
    *,
    final_state: torch.Tensor,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    if out is None and x.ndim == 3:
        out = torch.empty_strided(
            tuple(x.shape),
            tuple(x.stride()),
            device=x.device,
            dtype=x.dtype,
        )
    activation_supported, apply_silu = _conv_activation_supported(activation)
    supported = (
        _native.ops is not None
        and activation_supported
        and bias is None
        and out is not None
        and seq_idx is not None
        and x.device.type == "mps"
        and x.dtype in (torch.float16, torch.float32)
        and x.ndim == 3
        and x.numel() > 0
        and weight.ndim == 2
        and weight.shape[0] == x.shape[1]
        and weight.shape[1] > 0
        and weight.dtype == x.dtype
        and seq_idx.shape == (x.shape[0], x.shape[2])
        and seq_idx.dtype == torch.int32
        and final_state.ndim == 3
        and final_state.shape[1:] == (x.shape[1], weight.shape[1])
        and final_state.numel() > 0
        and final_state.dtype == x.dtype
        and out.shape == x.shape
        and out.dtype == x.dtype
        and weight.device == x.device
        and seq_idx.device == x.device
        and final_state.device == x.device
        and out.device == x.device
        and x.stride(1) == 1
        and out.stride(1) == 1
        and weight.is_contiguous()
        and seq_idx.is_contiguous()
        and final_state.is_contiguous()
    )
    if supported:
        _native.ops.causal_conv1d_packed(
            out,
            x,
            weight,
            seq_idx,
            final_state,
            apply_silu,
        )
        return out
    return causal_conv1d_packed_torch(
        x,
        weight,
        seq_idx,
        bias,
        activation,
        final_state=final_state,
        out=out,
    )


def packed_prefill_prepare_mps(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    *,
    query: torch.Tensor | None = None,
    key: torch.Tensor | None = None,
    value: torch.Tensor | None = None,
    g: torch.Tensor | None = None,
    beta: torch.Tensor | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    shape = (
        _infer_gqa_shape_from_mixed(int(mixed_qkv.shape[2]), int(a.shape[2]))
        if mixed_qkv.ndim == 3 and a.ndim == 3
        else None
    )
    if shape is None:
        return packed_prefill_prepare_torch(
            mixed_qkv,
            a,
            b,
            A_log,
            dt_bias,
            query=query,
            key=key,
            value=value,
            g=g,
            beta=beta,
        )
    num_k_heads, num_v_heads, head_dim = shape
    expected_query = (1, mixed_qkv.shape[1], num_k_heads, head_dim)
    expected_value = (1, mixed_qkv.shape[1], num_v_heads, head_dim)
    expected_3d = (1, mixed_qkv.shape[1], num_v_heads)
    if query is None:
        query = torch.empty(
            expected_query,
            device=mixed_qkv.device,
            dtype=mixed_qkv.dtype,
        )
    if key is None:
        key = torch.empty(
            expected_query,
            device=mixed_qkv.device,
            dtype=mixed_qkv.dtype,
        )
    if value is None:
        value = torch.empty(
            expected_value,
            device=mixed_qkv.device,
            dtype=mixed_qkv.dtype,
        )
    if g is None:
        g = torch.empty(expected_3d, device=mixed_qkv.device, dtype=torch.float32)
    if beta is None:
        beta = torch.empty(expected_3d, device=mixed_qkv.device, dtype=mixed_qkv.dtype)

    supported = (
        _native.ops is not None
        and mixed_qkv.device.type == "mps"
        and mixed_qkv.dtype in (torch.float16, torch.float32)
        and a.shape == expected_3d
        and b.shape == expected_3d
        and a.dtype == mixed_qkv.dtype
        and b.dtype == mixed_qkv.dtype
        and A_log.shape == (num_v_heads,)
        and dt_bias.shape == (num_v_heads,)
        and A_log.dtype == torch.float32
        and dt_bias.dtype == torch.float32
        and query.shape == expected_query
        and key.shape == expected_query
        and value.shape == expected_value
        and g.shape == expected_3d
        and beta.shape == expected_3d
        and query.dtype == mixed_qkv.dtype
        and key.dtype == mixed_qkv.dtype
        and value.dtype == mixed_qkv.dtype
        and g.dtype == torch.float32
        and beta.dtype == mixed_qkv.dtype
        and all(
            tensor.device == mixed_qkv.device
            for tensor in (a, b, A_log, dt_bias, query, key, value, g, beta)
        )
        and _packed_prefill_prepare_inputs_have_supported_layout(
            mixed_qkv,
            a,
            b,
            num_k_heads=num_k_heads,
            num_v_heads=num_v_heads,
            head_dim=head_dim,
        )
        and all(
            tensor.is_contiguous()
            for tensor in (
                A_log,
                dt_bias,
                query,
                key,
                value,
                g,
                beta,
            )
        )
        and query.is_contiguous()
        and key.is_contiguous()
        and value.is_contiguous()
        and g.is_contiguous()
        and beta.is_contiguous()
    )
    if supported:
        _native.ops.packed_prefill_prepare(
            query,
            key,
            value,
            g,
            beta,
            mixed_qkv.contiguous(),
            a.contiguous(),
            b.contiguous(),
            A_log.contiguous(),
            dt_bias.contiguous(),
        )
        return query, key, value, g, beta
    return packed_prefill_prepare_torch(
        mixed_qkv,
        a,
        b,
        A_log,
        dt_bias,
        query=query,
        key=key,
        value=value,
        g=g,
        beta=beta,
    )


def packed_gated_delta_rule_prefill_mps(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    cu_seqlens: torch.Tensor,
    *,
    workspace: PackedGatedDeltaPrefillWorkspace | None = None,
    initial_state: torch.Tensor | None = None,
    output_final_state: bool = True,
    sequence_lengths: Sequence[int] | None = None,
    topology_token: Any | None = None,
    out: torch.Tensor | None = None,
    final_state: torch.Tensor | None = None,
    final_state_indices: torch.Tensor | None = None,
    final_state_indices_allocator_owned: bool = False,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    shape = (
        _infer_gqa_shape_from_mixed(int(mixed_qkv.shape[2]), int(a.shape[2]))
        if mixed_qkv.ndim == 3 and a.ndim == 3
        else None
    )
    if shape is None:
        raise ValueError("cannot infer packed GDN prefill head geometry")
    tokens = int(mixed_qkv.shape[1])
    num_sequences = cu_seqlens.numel() - 1 if cu_seqlens.ndim == 1 else 0
    effective_cu_seqlens, _topology_authority = (
        _resolve_packed_prefill_topology_offsets(
            topology_token,
            cu_seqlens,
            sequence_lengths,
            num_sequences=num_sequences,
            total_tokens=tokens,
        )
    )
    memrefs = [a, b, A_log, dt_bias, cu_seqlens]
    memrefs.extend(
        tensor
        for tensor in (out, initial_state)
        if tensor is not None
    )
    if output_final_state:
        memrefs.extend(
            tensor
            for tensor in (final_state, final_state_indices)
            if tensor is not None
        )
    if any(tensor.device != mixed_qkv.device for tensor in memrefs):
        raise ValueError("packed GDN prefill tensors must share one device")
    if workspace is None:
        workspace = _allocate_prefill_workspace(
            mixed_qkv,
            a,
        )
    _, num_v_heads, head_dim = shape
    if not workspace.can_serve(mixed_qkv, a, head_dim=head_dim):
        raise RuntimeError(
            "packed GDN workspace cannot serve the current device/dtype/head "
            "geometry/token count"
        )
    active_workspace = workspace.for_tokens(tokens)
    if out is None:
        out = active_workspace.out
    else:
        if (
            out.ndim != 4
            or out.shape[0] != 1
            or out.shape[1] < tokens
            or out.shape[2:] != (num_v_heads, head_dim)
            or out.device != mixed_qkv.device
            or out.dtype != mixed_qkv.dtype
            or not out.is_contiguous()
        ):
            raise ValueError(
                "out does not satisfy packed GDN prefill capacity/device/dtype"
            )
        out = active_token_prefix(out, tokens)
    query, key, value, log_g, beta = packed_prefill_prepare_mps(
        mixed_qkv,
        a,
        b,
        A_log,
        dt_bias,
        query=active_workspace.query,
        key=active_workspace.key,
        value=active_workspace.value,
        g=active_workspace.log_g,
        beta=active_workspace.beta_bf16,
    )
    if not output_final_state:
        return packed_recurrent_gated_delta_rule_prefill_torch(
            query,
            key,
            value,
            log_g,
            beta,
            effective_cu_seqlens,
            initial_state=initial_state,
            output_final_state=False,
            out=out,
            final_state=None,
            final_state_indices=None,
        )
    return _packed_recurrent_gated_delta_rule_prefill_mps_resolved(
        query,
        key,
        value,
        log_g,
        beta,
        effective_cu_seqlens,
        topology_authority=_topology_authority,
        initial_state=initial_state,
        output_final_state=output_final_state,
        out=out,
        final_state=final_state,
        final_state_indices=final_state_indices,
        final_state_indices_allocator_owned=final_state_indices_allocator_owned,
    )


def packed_recurrent_gated_delta_rule_decode_replay_indexed_mps(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    checkpoint_state: torch.Tensor,
    replay_k: torch.Tensor,
    replay_u: torch.Tensor,
    replay_g: torch.Tensor,
    replay_lengths: torch.Tensor,
    state_indices: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
) -> tuple[torch.Tensor, None]:
    if out is None and checkpoint_state.ndim == 4:
        out = torch.empty(
            (
                mixed_qkv.shape[0],
                1,
                checkpoint_state.shape[1],
                checkpoint_state.shape[2],
            ),
            device=mixed_qkv.device,
            dtype=mixed_qkv.dtype,
        )
    capacity = int(replay_k.shape[1]) if replay_k.ndim == 4 else -1
    shape = (
        _infer_gqa_shape_from_mixed(
            int(mixed_qkv.shape[1]),
            int(checkpoint_state.shape[1]),
            int(checkpoint_state.shape[3]),
        )
        if mixed_qkv.ndim == 2 and checkpoint_state.ndim == 4
        else None
    )
    supported = False
    if out is not None and shape is not None:
        num_k_heads, num_v_heads, head_dim = shape
        expected_out = (mixed_qkv.shape[0], 1, num_v_heads, head_dim)
        supported = (
            _native.ops is not None
            and capacity in _MPS_REPLAY_CAPACITIES
            and mixed_qkv.device.type == "mps"
            and mixed_qkv.dtype in (torch.float16, torch.float32)
            and a.shape == (mixed_qkv.shape[0], 1, num_v_heads)
            and b.shape == (mixed_qkv.shape[0], 1, num_v_heads)
            and a.dtype == mixed_qkv.dtype
            and b.dtype == mixed_qkv.dtype
            and A_log.shape == (num_v_heads,)
            and dt_bias.shape == (num_v_heads,)
            and A_log.dtype == torch.float32
            and dt_bias.dtype == torch.float32
            and checkpoint_state.shape == (
                checkpoint_state.shape[0],
                num_v_heads,
                head_dim,
                head_dim,
            )
            and checkpoint_state.dtype == torch.float32
            and replay_k.shape == (
                checkpoint_state.shape[0],
                capacity,
                num_k_heads,
                head_dim,
            )
            and replay_k.dtype == mixed_qkv.dtype
            and replay_u.shape == (
                checkpoint_state.shape[0],
                capacity,
                num_v_heads,
                head_dim,
            )
            and replay_u.dtype == torch.float32
            and replay_g.shape == (checkpoint_state.shape[0], capacity, num_v_heads)
            and replay_g.dtype == torch.float32
            and replay_lengths.shape == (checkpoint_state.shape[0],)
            and replay_lengths.dtype == torch.int32
            and state_indices.shape == (mixed_qkv.shape[0],)
            and state_indices.dtype == torch.long
            and out.shape == expected_out
            and out.dtype == mixed_qkv.dtype
            and mixed_qkv.is_contiguous()
            and checkpoint_state.is_contiguous()
            and replay_k.is_contiguous()
            and replay_u.is_contiguous()
            and replay_g.is_contiguous()
            and replay_lengths.is_contiguous()
            and state_indices.is_contiguous()
            and out.is_contiguous()
        )
    if supported:
        _native.ops.packed_recurrent_gdn_decode_replay_indexed(
            out,
            mixed_qkv,
            a.contiguous(),
            b.contiguous(),
            A_log.contiguous(),
            dt_bias.contiguous(),
            checkpoint_state,
            replay_k,
            replay_u,
            replay_g,
            replay_lengths,
            state_indices,
        )
        return out, None
    return packed_recurrent_gated_delta_rule_decode_replay_indexed_torch(
        mixed_qkv,
        a,
        b,
        A_log,
        dt_bias,
        checkpoint_state,
        replay_k,
        replay_u,
        replay_g,
        replay_lengths,
        state_indices,
        out=out,
    )


def packed_recurrent_gated_delta_rule_prefill_mps(
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    g: torch.Tensor,
    beta: torch.Tensor,
    cu_seqlens: torch.Tensor,
    *,
    initial_state: torch.Tensor | None = None,
    output_final_state: bool = True,
    use_qk_l2norm_in_kernel: bool = False,
    sequence_lengths: Sequence[int] | None = None,
    topology_token: Any | None = None,
    out: torch.Tensor | None = None,
    final_state: torch.Tensor | None = None,
    final_state_indices: torch.Tensor | None = None,
    final_state_indices_allocator_owned: bool = False,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    num_sequences = cu_seqlens.numel() - 1 if cu_seqlens.ndim == 1 else 0
    total_tokens = int(query.shape[1]) if query.ndim == 4 else -1
    effective_cu_seqlens, topology_authority = (
        _resolve_packed_prefill_topology_offsets(
            topology_token,
            cu_seqlens,
            sequence_lengths,
            num_sequences=num_sequences,
            total_tokens=total_tokens,
        )
    )
    return _packed_recurrent_gated_delta_rule_prefill_mps_resolved(
        query,
        key,
        value,
        g,
        beta,
        effective_cu_seqlens,
        topology_authority=topology_authority,
        initial_state=initial_state,
        output_final_state=output_final_state,
        use_qk_l2norm_in_kernel=use_qk_l2norm_in_kernel,
        out=out,
        final_state=final_state,
        final_state_indices=final_state_indices,
        final_state_indices_allocator_owned=final_state_indices_allocator_owned,
    )


def _packed_recurrent_gated_delta_rule_prefill_mps_resolved(
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    g: torch.Tensor,
    beta: torch.Tensor,
    effective_cu_seqlens: torch.Tensor,
    *,
    topology_authority: Any,
    initial_state: torch.Tensor | None = None,
    output_final_state: bool = True,
    use_qk_l2norm_in_kernel: bool = False,
    out: torch.Tensor | None = None,
    final_state: torch.Tensor | None = None,
    final_state_indices: torch.Tensor | None = None,
    final_state_indices_allocator_owned: bool = False,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    """Execute MPS recurrent prefill from one resolved topology snapshot."""

    if query.ndim == 4 and value.ndim == 4:
        expected_out = (1, query.shape[1], value.shape[2], value.shape[3])
        if out is None:
            out = torch.empty(expected_out, device=query.device, dtype=query.dtype)
        if (
            output_final_state
            and final_state is None
            and final_state_indices is None
            and effective_cu_seqlens.ndim == 1
        ):
            final_state = torch.empty(
                (
                    effective_cu_seqlens.numel() - 1,
                    value.shape[2],
                    query.shape[3],
                    value.shape[3],
                ),
                device=query.device,
                dtype=torch.float32,
            )
    if not output_final_state:
        return packed_recurrent_gated_delta_rule_prefill_torch(
            query,
            key,
            value,
            g,
            beta,
            effective_cu_seqlens,
            initial_state=initial_state,
            output_final_state=False,
            use_qk_l2norm_in_kernel=use_qk_l2norm_in_kernel,
            out=out,
            final_state=None,
            final_state_indices=None,
        )
    if final_state_indices is not None:
        # MPS has no native indexed writer, so allocator provenance does not
        # bypass the fallback's bounds and uniqueness checks.
        return packed_recurrent_gated_delta_rule_prefill_torch(
            query,
            key,
            value,
            g,
            beta,
            effective_cu_seqlens,
            initial_state=initial_state,
            output_final_state=True,
            use_qk_l2norm_in_kernel=use_qk_l2norm_in_kernel,
            out=out,
            final_state=final_state,
            final_state_indices=final_state_indices,
        )
    supported = (
        topology_authority is not None
        and _native.ops is not None
        and query.device.type == "mps"
        and query.dtype in (torch.float16, torch.float32)
        and query.ndim == 4
        and query.shape[0] == 1
        and query.shape[2] > 0
        and value.ndim == 4
        and g.ndim == 3
        and beta.ndim == 3
        and key.shape == query.shape
        and value.shape == (1, query.shape[1], value.shape[2], query.shape[3])
        and value.dtype == query.dtype
        and key.dtype == query.dtype
        and g.shape == (1, query.shape[1], value.shape[2])
        and beta.shape == g.shape
        and g.dtype == torch.float32
        and beta.dtype == query.dtype
        and effective_cu_seqlens.device == query.device
        and effective_cu_seqlens.dtype == torch.int32
        and effective_cu_seqlens.ndim == 1
        and out is not None
        and out.shape == (1, query.shape[1], value.shape[2], query.shape[3])
        and out.dtype == query.dtype
        and final_state is not None
        and final_state.shape == (
            effective_cu_seqlens.numel() - 1,
            value.shape[2],
            query.shape[3],
            query.shape[3],
        )
        and final_state.dtype == torch.float32
        and all(
            tensor.device == query.device
            for tensor in (
                key,
                value,
                g,
                beta,
                effective_cu_seqlens,
                out,
                final_state,
            )
        )
        and query.shape[3] == _QWEN_HEAD_DIM
        and value.shape[2] % query.shape[2] == 0
        and initial_state is None
        and not use_qk_l2norm_in_kernel
        and query.is_contiguous()
        and key.is_contiguous()
        and value.is_contiguous()
        and g.is_contiguous()
        and beta.is_contiguous()
        and effective_cu_seqlens.is_contiguous()
        and out.is_contiguous()
        and final_state.is_contiguous()
    )
    if supported:
        _native.ops.packed_recurrent_gdn_prefill(
            out,
            query,
            key,
            value,
            g,
            beta,
            effective_cu_seqlens,
            final_state,
        )
        return out, final_state if output_final_state else None
    return packed_recurrent_gated_delta_rule_prefill_torch(
        query,
        key,
        value,
        g,
        beta,
        effective_cu_seqlens,
        initial_state=initial_state,
        output_final_state=output_final_state,
        use_qk_l2norm_in_kernel=use_qk_l2norm_in_kernel,
        out=out,
        final_state=final_state,
        final_state_indices=final_state_indices,
    )


def _supports_native_gated_rmsnorm(
    hidden_states: torch.Tensor,
    gate: torch.Tensor,
    weight: torch.Tensor,
    out: torch.Tensor,
) -> bool:
    if _native.ops is None:
        return False
    if hidden_states.ndim == 0 or hidden_states.shape[-1] == 0:
        return False
    return (
        hidden_states.device.type == "mps"
        and gate.device.type == "mps"
        and weight.device.type == "mps"
        and out.device.type == "mps"
        and hidden_states.dtype in (torch.float16, torch.float32)
        and gate.dtype == hidden_states.dtype
        and out.dtype == hidden_states.dtype
        and weight.dtype == torch.float32
        and hidden_states.shape == gate.shape
        and out.shape == hidden_states.shape
        and weight.shape == (hidden_states.shape[-1],)
        and hidden_states.is_contiguous()
        and gate.is_contiguous()
        and out.is_contiguous()
        and weight.is_contiguous()
        and hidden_states.shape[-1] % 4 == 0
        and hidden_states.shape[-1] <= 4096
    )


def gated_rmsnorm_mps(
    hidden_states: torch.Tensor,
    gate: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1e-6,
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    if gate is None:
        raise ValueError("gated_rmsnorm_mps requires a gate tensor")
    if out is None:
        out = torch.empty_like(hidden_states, memory_format=torch.contiguous_format)
    if hidden_states.numel() == 0:
        if hidden_states.shape != gate.shape:
            raise ValueError(
                "hidden_states and gate must have the same shape, got "
                f"{tuple(hidden_states.shape)} and {tuple(gate.shape)}"
            )
        expected_weight_shape = (hidden_states.shape[-1],)
        if weight.shape != expected_weight_shape:
            raise ValueError(
                f"weight shape must be {expected_weight_shape}, got "
                f"{tuple(weight.shape)}"
            )
        if out.shape != hidden_states.shape:
            raise ValueError(
                f"out shape must be {tuple(hidden_states.shape)}, got "
                f"{tuple(out.shape)}"
            )
        return out
    if _supports_native_gated_rmsnorm(hidden_states, gate, weight, out):
        _native.ops.gated_rms_norm(out, hidden_states, gate, weight, float(eps))
        return out
    return gated_rmsnorm_torch(hidden_states, gate, weight, eps, out=out)


